"use strict";(globalThis.webpackChunkblog=globalThis.webpackChunkblog||[]).push([[1284],{26801(e,n,a){a.r(n),a.d(n,{assets:()=>l,contentTitle:()=>r,default:()=>h,frontMatter:()=>o,metadata:()=>t,toc:()=>d});var t=a(46777),i=a(74848),s=a(28453);const o={title:"GRC for AI: A Beginner's Guide to Governance, Risk, and Compliance",author:"Rishi Shukla",date:"2026-09-26",tags:["GRC","AI Governance","Cybersecurity","Compliance","ISO 42001","NIST AI RMF","DPDP Act"]},r="GRC for AI: A Beginner's Guide to Governance, Risk, and Compliance",l={authorsImageUrls:[void 0]},d=[{value:"What is GRC?",id:"what-is-grc",level:2},{value:"The AI Risk Landscape: Why This Suddenly Matters",id:"the-ai-risk-landscape-why-this-suddenly-matters",level:2},{value:"Example: BFSI (Banking, Financial Services, and Insurance)",id:"example-bfsi-banking-financial-services-and-insurance",level:3},{value:"Adapting Your GRC Framework for AI",id:"adapting-your-grc-framework-for-ai",level:2},{value:"A Simple Mental Model: 4 Layers of AI Governance",id:"a-simple-mental-model-4-layers-of-ai-governance",level:2},{value:"Regulator Reality: The Laws You Actually Have to Follow (India Focus)",id:"regulator-reality-the-laws-you-actually-have-to-follow-india-focus",level:2},{value:"What AI Teams Must Know About the DPDP Act, 2023",id:"what-ai-teams-must-know-about-the-dpdp-act-2023",level:3},{value:"Data Fiduciary: Who&#39;s Responsible?",id:"data-fiduciary-whos-responsible",level:2},{value:"What Happens If There&#39;s a Breach?",id:"what-happens-if-theres-a-breach",level:3},{value:"Shadow AI: The Risk Most Organizations Underestimate",id:"shadow-ai-the-risk-most-organizations-underestimate",level:2},{value:"5 Things a GRC Team Should Do to Get Started",id:"5-things-a-grc-team-should-do-to-get-started",level:2},{value:"The CISO&#39;s AI GRC Charter",id:"the-cisos-ai-grc-charter",level:2},{value:"Sources",id:"sources",level:2}];function c(e){const n={a:"a",em:"em",h2:"h2",h3:"h3",hr:"hr",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(n.p,{children:["Imagine you walk into your bank and apply for a loan. You hand over your salary slips, your PAN card, your address, your spending history. That data doesn't just sit in a drawer \u2014 the bank uses it, stores it, and shares parts of it with credit bureaus, insurers, and regulators. But there's one thing the bank is ",(0,i.jsx)(n.em,{children:"not"})," allowed to do: hand your data over to some random third party so that party can profit from it. Banking regulation exists precisely to stop that."]}),"\n",(0,i.jsx)(n.p,{children:"Now compare that to a free AI chatbot. Paste the same salary slip into it to \"summarize my finances,\" and by default, on many consumer AI tools, that conversation can be stored and used to improve the company's models \u2014 unless you specifically go into settings and opt out. It's not illegal, it's usually disclosed somewhere in the terms of service, but it's a completely different data relationship than the one you have with your bank. Nobody signed you up for it explicitly, and most people never read the settings page closely enough to notice."}),"\n",(0,i.jsxs)(n.p,{children:['That gap \u2014 the difference between "data handled inside a regulated, accountable system" and "data handled inside a system with looser or unclear rules" \u2014 is exactly the problem ',(0,i.jsx)(n.strong,{children:"GRC"})," exists to close."]}),"\n",(0,i.jsx)(n.p,{children:"This post breaks down what GRC is, why it suddenly matters so much in the age of AI, and how organizations actually use it \u2014 in plain language, with real examples."}),"\n",(0,i.jsx)(n.h2,{id:"what-is-grc",children:"What is GRC?"}),"\n",(0,i.jsxs)(n.p,{children:["GRC stands for ",(0,i.jsx)(n.strong,{children:"Governance, Risk, and Compliance"}),"."]}),"\n",(0,i.jsx)(n.p,{children:"It's a structured approach organizations use to make sure technology (and now, specifically, AI) is used safely, responsibly, and within the law \u2014 instead of everything happening in an unmonitored, ad-hoc way."}),"\n",(0,i.jsx)(n.p,{children:"A simple way to think about the three pieces:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Governance"})," \u2014 who decides the rules, and who is accountable for them. In the bank example, this is the bank's internal data-handling policy plus the regulations RBI imposes on it."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Risk"})," \u2014 what could go wrong, and how likely and damaging is it. What happens if that salary data leaks? What happens if an AI model trained partly on customer data starts leaking patterns back out to other users?"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Compliance"})," \u2014 are we actually following the laws and standards we're supposed to. Is the bank actually enforcing its own policy, or is it just a PDF nobody reads?"]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"the-ai-risk-landscape-why-this-suddenly-matters",children:"The AI Risk Landscape: Why This Suddenly Matters"}),"\n",(0,i.jsxs)(n.p,{children:["Here's a scenario almost everyone can relate to: we give AI tools like ChatGPT ",(0,i.jsx)(n.em,{children:"everything"})," \u2014 our questions, our documents, sometimes even sensitive company data \u2014 but we rarely stop to ask what happens to that data after we hit send."]}),"\n",(0,i.jsxs)(n.p,{children:["This isn't hypothetical. In 2023, engineers at ",(0,i.jsx)(n.strong,{children:"Samsung's semiconductor division"})," pasted confidential source code and internal meeting notes into ChatGPT to get help fixing bugs and summarizing meetings. Because that data left the company's systems and entered a third-party AI tool, Samsung had no way to guarantee it wouldn't be retained, reviewed, or used elsewhere. The company responded by banning generative AI tools on company devices entirely and started building internal AI tools instead. This single incident is now one of the most cited case studies in enterprise AI governance \u2014 it's the textbook example of what happens when there's no GRC policy governing how employees use AI."]}),"\n",(0,i.jsx)(n.p,{children:"Many people assume \"it's fine, our data probably doesn't leave our country\" or \"surely they don't actually use my chats\" \u2014 but those are assumptions, not guarantees, and they depend entirely on the specific tool, its data-residency settings, its subscription tier, and its contract terms. For instance, OpenAI has stated that consumer ChatGPT conversations may by default be used to help train and improve its models unless the user actively opts out in settings \u2014 while its business/API tiers are handled differently. That's a legitimate business practice, disclosed in the terms of service \u2014 but it's precisely the kind of detail a GRC framework forces an organization to actually check, rather than assume."}),"\n",(0,i.jsx)(n.p,{children:"This is exactly why organizations that handle sensitive data increasingly look at private, self-hosted, or enterprise-tier AI deployments \u2014 with contractual guarantees around data use \u2014 rather than relying purely on free public AI tools."}),"\n",(0,i.jsx)(n.h3,{id:"example-bfsi-banking-financial-services-and-insurance",children:"Example: BFSI (Banking, Financial Services, and Insurance)"}),"\n",(0,i.jsxs)(n.p,{children:["This is exactly why the ",(0,i.jsx)(n.strong,{children:"BFSI sector"})," is so cautious with AI. A bank can't let customer financial data flow freely into an external AI tool \u2014 a leak here isn't just embarrassing, it can trigger regulatory penalties, lawsuits, and a total collapse of customer trust. Going back to our opening example: the bank is bound, by law and by contract, to protect your salary data. A general-purpose AI company with no such binding relationship to you is under no obligation to treat your data with the same level of care \u2014 unless a GRC framework is deliberately built to require it."]}),"\n",(0,i.jsx)(n.p,{children:"This is where GRC steps in: it creates rules for how AI can be used, and shapes those rules so that data stays safe and the organization stays accountable \u2014 closing exactly the gap illustrated above."}),"\n",(0,i.jsx)(n.h2,{id:"adapting-your-grc-framework-for-ai",children:"Adapting Your GRC Framework for AI"}),"\n",(0,i.jsx)(n.p,{children:"AI systems make mistakes \u2014 they can hallucinate facts, encode bias, or leak information they shouldn't. Because of this, organizations are adapting their GRC programs with AI-specific standards and frameworks. Here are the major ones, explained simply:"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"ISO/IEC 27001"})," \u2014 the long-standing international standard for information security management systems (ISMS). It's about protecting ",(0,i.jsx)(n.em,{children:"all"})," organizational information, not AI-specific, but it's the foundation most AI governance work builds on top of."]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"ISO/IEC 42001"})," \u2014 the world's first international standard specifically for an ",(0,i.jsx)(n.strong,{children:"AI Management System (AIMS)"}),", published in December 2023. It gives organizations a certifiable, auditable way to govern how they develop, provide, or use AI \u2014 covering things like risk assessment, transparency, and accountability across the AI lifecycle. Companies including AWS, Microsoft, and Anthropic have been certified against it."]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"NIST AI Risk Management Framework (AI RMF)"})," \u2014 a voluntary framework from the US National Institute of Standards and Technology, first published in January 2023. It's built around four core functions:"]}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Govern"})," \u2014 build the culture, policies, and accountability structures that hold everything together"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Map"})," \u2014 understand the context: what is this AI system for, who does it affect, what could go wrong"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Measure"})," \u2014 actually test and quantify the risks (bias, security gaps, reliability issues)"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Manage"})," \u2014 act on what you found: prioritize, fix, and keep monitoring"]}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:["In July 2024, NIST extended this with a ",(0,i.jsx)(n.strong,{children:"Generative AI Profile"}),", adding risk categories specific to large language models \u2014 things like hallucination, data poisoning, and misuse for harmful content generation. Unlike ISO 42001, the NIST AI RMF is ",(0,i.jsx)(n.strong,{children:"not certifiable"})," \u2014 it's a shared vocabulary and methodology, not a badge you can earn."]}),"\n"]}),"\n",(0,i.jsxs)(n.li,{children:["\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"RBI / SEBI"})," \u2014 India's financial regulators. The most significant recent development here is the RBI's ",(0,i.jsx)(n.strong,{children:"FREE-AI Framework"}),' (Framework for Responsible and Ethical Enablement of Artificial Intelligence), released on 13 August 2025 after a committee chaired by IIT Bombay\'s Prof. Pushpak Bhattacharyya. It sets out 7 guiding principles ("Sutras") and 26 recommendations across six pillars \u2014 Infrastructure, Policy, Capacity, Governance, Protection, and Assurance \u2014 for how Indian banks, NBFCs, and fintechs should govern their use of AI, covering bias, explainability, cybersecurity, and incident reporting.']}),"\n"]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"a-simple-mental-model-4-layers-of-ai-governance",children:"A Simple Mental Model: 4 Layers of AI Governance"}),"\n",(0,i.jsx)(n.p,{children:"Beyond specific standards, it helps to have a simple internal model for how AI governance actually works day-to-day inside a team. One useful way to structure it:"}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"1. Govern"}),"\nDecide the policies and rules for how AI can and can't be used in the organization. This includes staying current \u2014 following credible security and AI governance blogs, vendor advisories, and regulator updates. This is also where an organization would have written the rule Samsung didn't have in early 2023: \"do not paste source code or confidential documents into third-party AI tools.\""]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"2. Identify"}),"\nActively look for vulnerabilities and risks in your AI systems. A classic example: your AI model might be biased against certain groups \u2014 for instance, evaluating loan applications less favorably for one demographic than another purely due to skewed training data. Catching this early is the whole point of this step."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"3. Control"}),"\nOnce a risk is identified, put safeguards in place to prevent it from actually happening \u2014 access controls, output filtering, human review for high-stakes decisions, blocking uploads of certain file types to consumer AI tools, and so on."]}),"\n",(0,i.jsxs)(n.p,{children:[(0,i.jsx)(n.strong,{children:"4. Monitor"}),"\nGovernance doesn't stop at deployment. This is the continuous work of watching the AI system in production to make sure it keeps behaving as expected \u2014 and watching ",(0,i.jsx)(n.em,{children:"how employees are actually using AI tools"})," day to day, since that's where most real-world incidents (like Samsung's) actually happen."]}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.em,{children:"(Note: this four-layer model is a practical mental map for teams, not a formal named standard \u2014 it's a simplified way to think through the lifecycle, distinct from the official NIST AI RMF functions listed above.)"})}),"\n",(0,i.jsx)(n.h2,{id:"regulator-reality-the-laws-you-actually-have-to-follow-india-focus",children:"Regulator Reality: The Laws You Actually Have to Follow (India Focus)"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"DPDP Act, 2023"})," (Digital Personal Data Protection Act) \u2014 India's dedicated personal data protection law, enacted 11 August 2023."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"RBI Master Directions / FREE-AI Framework"})," \u2014 sector-specific rules and guidance for regulated financial entities."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"ISO/IEC standards"})," \u2014 including 27001 and 42001, discussed above."]}),"\n"]}),"\n",(0,i.jsx)(n.h3,{id:"what-ai-teams-must-know-about-the-dpdp-act-2023",children:"What AI Teams Must Know About the DPDP Act, 2023"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Consent is central."})," Processing personal data generally requires clear, informed consent from the \"Data Principal\" (the individual the data belongs to) \u2014 organizations can't assume old consent automatically covers new AI use cases. This is exactly the difference between our bank and AI-chatbot example: the bank has explicit consent for a defined purpose (processing your loan), while a general AI tool's consent is buried in a terms-of-service checkbox most people never read."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Extra protection for children's data."})," The Act requires verifiable parental/guardian consent before processing a child's personal data, and bars tracking, behavioral monitoring, or targeted advertising directed at children."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Right to grievance redressal and correction."})," Data Principals have rights including access, correction, erasure, and grievance redressal \u2014 companies need to be able to explain how someone's data is being used."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"A dedicated regulator exists."})," The ",(0,i.jsx)(n.strong,{children:"Data Protection Board of India (DPBI)"})," handles breach investigations, complaints, and enforcement."]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Penalties are significant."})," Depending on the violation, financial penalties can reach up to \u20b9250 crore (roughly USD 30 million) for failing to implement reasonable security safeguards leading to a breach, with other violation categories carrying penalties up to \u20b9200 crore or \u20b950 crore. Individuals (Data Principals) can also be fined up to \u20b910,000 for violating their own duties under the Act, such as furnishing false information."]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"data-fiduciary-whos-responsible",children:"Data Fiduciary: Who's Responsible?"}),"\n",(0,i.jsxs)(n.p,{children:["Under the DPDP Act, any entity that decides ",(0,i.jsx)(n.em,{children:"why"})," and ",(0,i.jsx)(n.em,{children:"how"})," personal data is processed is called a ",(0,i.jsx)(n.strong,{children:"Data Fiduciary"}),", and it is directly responsible for protecting that data \u2014 this is not optional. Your bank is a Data Fiduciary for your loan data. If a company builds an internal AI tool that processes customer data, that company becomes a Data Fiduciary for whatever that AI tool touches too \u2014 the obligation follows the data, not just the original collection point."]}),"\n",(0,i.jsx)(n.h3,{id:"what-happens-if-theres-a-breach",children:"What Happens If There's a Breach?"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"If a breach occurs, the Data Fiduciary is expected to notify the Data Protection Board and the affected individuals without undue delay so they can protect themselves."}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Penalties"})," scale with the severity and nature of the violation, as outlined above \u2014 this is exactly why GRC isn't just paperwork; it has real financial and legal consequences attached to it."]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"shadow-ai-the-risk-most-organizations-underestimate",children:"Shadow AI: The Risk Most Organizations Underestimate"}),"\n",(0,i.jsxs)(n.p,{children:["One risk worth calling out on its own: ",(0,i.jsx)(n.strong,{children:'"Shadow AI"'})," \u2014 employees using AI tools the organization never approved, reviewed, or even knows about. Samsung's 2023 incident is a textbook Shadow AI case: individual engineers, trying to be helpful and efficient, used a public tool without realizing they were moving confidential data outside the company's control. A mature GRC program doesn't just write a policy and hope people read it \u2014 it actively looks for where AI tools are already being used across the organization (browser extensions, personal accounts, free-tier signups) so it can bring that usage under governance rather than banning it outright and pushing it further underground."]}),"\n",(0,i.jsx)(n.h2,{id:"5-things-a-grc-team-should-do-to-get-started",children:"5 Things a GRC Team Should Do to Get Started"}),"\n",(0,i.jsx)(n.p,{children:"If an organization wants to get serious about AI GRC, here's a simple starting checklist:"}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Build an AI inventory"})," \u2014 know exactly which AI tools and models are being used across the organization, including the kind of Shadow AI usage described above"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Appoint an AI risk owner"})," \u2014 someone directly accountable for AI-related risk decisions"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Run a DPDP consent audit"})," \u2014 verify that valid, specific consent actually exists for how data is being used with AI tools"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Pilot ISO/IEC 42001 controls"})," \u2014 start testing this AI-specific management system standard in one business unit before rolling it out organization-wide"]}),"\n",(0,i.jsxs)(n.li,{children:[(0,i.jsx)(n.strong,{children:"Brief the board"})," \u2014 make sure leadership understands the risks involved and is aligned on the governance plan"]}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"the-cisos-ai-grc-charter",children:"The CISO's AI GRC Charter"}),"\n",(0,i.jsx)(n.p,{children:"At the end of the day, it comes down to a simple idea:"}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.strong,{children:"GRC professionals are the new guardians of trustworthy AI."})}),"\n",(0,i.jsx)(n.p,{children:'As AI becomes part of everyday business operations, the people managing Governance, Risk, and Compliance aren\'t "checking boxes" anymore \u2014 they\'re the ones standing between an organization and serious data, legal, and reputational damage. The line between "a bank that protects your data" and "a tool that quietly trains on it" isn\'t drawn by the technology itself \u2014 it\'s drawn by governance.'}),"\n",(0,i.jsx)(n.hr,{}),"\n",(0,i.jsx)(n.p,{children:(0,i.jsx)(n.em,{children:"That's GRC in a nutshell: it's not about slowing AI down \u2014 it's about making sure it's used responsibly enough that it doesn't blow up in an organization's face later."})}),"\n",(0,i.jsx)(n.h2,{id:"sources",children:"Sources"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsxs)(n.li,{children:["ISO \u2014 ",(0,i.jsx)(n.a,{href:"https://www.iso.org/home/insights-news/resources/iso-42001-explained-what-it-is.html",children:"ISO/IEC 42001 explained"})]}),"\n",(0,i.jsx)(n.li,{children:"NIST \u2014 AI Risk Management Framework (AI RMF 1.0), January 2023; Generative AI Profile (NIST AI 600-1), July 2024"}),"\n",(0,i.jsx)(n.li,{children:"Reserve Bank of India \u2014 FREE-AI Committee Report, 13 August 2025"}),"\n",(0,i.jsx)(n.li,{children:"Digital Personal Data Protection Act, 2023 (Act 22 of 2023), Government of India"}),"\n",(0,i.jsx)(n.li,{children:"Bloomberg / Fortune \u2014 Samsung ChatGPT data leak and generative AI ban, May 2023"}),"\n",(0,i.jsx)(n.li,{children:'OpenAI \u2014 "How your data is used to improve model performance," Data Controls FAQ'}),"\n"]})]})}function h(e={}){const{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}},28453(e,n,a){a.d(n,{R:()=>o,x:()=>r});var t=a(96540);const i={},s=t.createContext(i);function o(e){const n=t.useContext(s);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),t.createElement(s.Provider,{value:n},e.children)}},46777(e){e.exports=JSON.parse('{"permalink":"/blog/24rishishukla-dev/grc-for-ai","source":"@site/blog/24rishishukla-dev/grc-for-ai.md","title":"GRC for AI: A Beginner\'s Guide to Governance, Risk, and Compliance","description":"Imagine you walk into your bank and apply for a loan. You hand over your salary slips, your PAN card, your address, your spending history. That data doesn\'t just sit in a drawer \u2014 the bank uses it, stores it, and shares parts of it with credit bureaus, insurers, and regulators. But there\'s one thing the bank is not allowed to do: hand your data over to some random third party so that party can profit from it. Banking regulation exists precisely to stop that.","date":"2026-09-26T00:00:00.000Z","tags":[{"inline":true,"label":"GRC","permalink":"/blog/tags/grc"},{"inline":true,"label":"AI Governance","permalink":"/blog/tags/ai-governance"},{"inline":true,"label":"Cybersecurity","permalink":"/blog/tags/cybersecurity"},{"inline":true,"label":"Compliance","permalink":"/blog/tags/compliance"},{"inline":true,"label":"ISO 42001","permalink":"/blog/tags/iso-42001"},{"inline":true,"label":"NIST AI RMF","permalink":"/blog/tags/nist-ai-rmf"},{"inline":true,"label":"DPDP Act","permalink":"/blog/tags/dpdp-act"}],"readingTime":11.68,"hasTruncateMarker":false,"authors":[{"name":"Rishi Shukla","key":null,"page":null}],"frontMatter":{"title":"GRC for AI: A Beginner\'s Guide to Governance, Risk, and Compliance","author":"Rishi Shukla","date":"2026-09-26","tags":["GRC","AI Governance","Cybersecurity","Compliance","ISO 42001","NIST AI RMF","DPDP Act"]},"unlisted":false,"nextItem":{"title":"This Week: A Perfect 10, an AI Agent Blind Spot, and ClickFix Everywhere","permalink":"/blog/this-week-trusted-things-behaving-badly"}}')}}]);